import{_ as t,a,o as s,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"GDPR Data Requests","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/gdpr-requests/index.md","filePath":"api/graphql-api/shop/gdpr-requests/index.md","lastUpdated":1786429091000}'),d={name:"api/graphql-api/shop/gdpr-requests/index.md"};function o(i,e,n,h,p,l){return s(),a("div",null,e[0]||(e[0]=[r(`<h1 id="gdpr-data-requests" tabindex="-1">GDPR Data Requests <a class="header-anchor" href="#gdpr-data-requests" aria-label="Permalink to &quot;GDPR Data Requests&quot;">​</a></h1><p>GDPR data requests let a logged-in customer exercise their data-protection rights — asking the store to <strong>delete</strong> their account data or to <strong>update</strong> the personal data held about them. Every request is created, listed, viewed, revoked and deleted by the customer who owns it; a customer can only ever see and act on their own requests.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All GDPR endpoints require an authenticated <strong>customer</strong> — provide the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page for how to obtain and send them.</p><h2 id="gdpr-must-be-enabled-by-the-store" tabindex="-1">GDPR must be enabled by the store <a class="header-anchor" href="#gdpr-must-be-enabled-by-the-store" aria-label="Permalink to &quot;GDPR must be enabled by the store&quot;">​</a></h2><p>Every GDPR operation first checks whether GDPR data requests are switched on in the store&#39;s admin configuration. <strong>If GDPR is turned off, the call fails</strong> with an <code>errors[]</code> entry:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;errors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When you see this message, the feature has been disabled on the admin side — it must be re-enabled in the store&#39;s admin configuration before any GDPR request can be raised, listed, revoked or deleted.</p><h2 id="request-lifecycle" tabindex="-1">Request lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request lifecycle&quot;">​</a></h2><p>A GDPR request moves through these statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pending</code></td><td>The request was just raised and is awaiting review.</td></tr><tr><td><code>processing</code></td><td>The store has started working on the request.</td></tr><tr><td><code>declined</code></td><td>The store reviewed and declined the request.</td></tr><tr><td><code>approved</code></td><td>The store reviewed and approved (fulfilled) the request.</td></tr><tr><td><code>revoked</code></td><td>The customer withdrew the request before it was finished.</td></tr></tbody></table><p>A customer raises a request (<code>pending</code>), can <strong>revoke</strong> it while it is still <code>pending</code> or <code>processing</code>, and can <strong>delete</strong> the request record entirely. Revoking a request that has already been declined, approved, or revoked is rejected — only the first two states can be withdrawn.</p><p>Only the store moves a request into <code>processing</code>, <code>declined</code>, or <code>approved</code>; those transitions are not available through the storefront API.</p><h2 id="request-type" tabindex="-1">Request type <a class="header-anchor" href="#request-type" aria-label="Permalink to &quot;Request type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>delete</code></td><td>Request the store to delete the customer&#39;s account data.</td></tr><tr><td><code>update</code></td><td>Request the store to update the personal data held about the customer.</td></tr></tbody></table><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th><th>Description</th></tr></thead><tbody><tr><td>List own requests</td><td><a href="/api/graphql-api/shop/gdpr-requests/queries/list-gdpr-requests.html"><code>gdprRequests</code></a></td><td>Paginated list of the customer&#39;s own GDPR requests.</td></tr><tr><td>View one request</td><td><a href="/api/graphql-api/shop/gdpr-requests/queries/view-gdpr-request.html"><code>gdprRequest</code></a></td><td>A single request the customer owns.</td></tr><tr><td>Raise a request</td><td><a href="/api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.html"><code>createGdprRequest</code></a></td><td>Raise a new <code>delete</code> or <code>update</code> request.</td></tr><tr><td>Revoke a request</td><td><a href="/api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.html"><code>revokeGdprRequest</code></a></td><td>Withdraw a <code>pending</code> / <code>processing</code> request.</td></tr><tr><td>Delete a request</td><td><a href="/api/graphql-api/shop/gdpr-requests/mutations/delete-gdpr-request.html"><code>deleteGdprRequest</code></a></td><td>Remove a request record.</td></tr></tbody></table>`,17)]))}const q=t(d,[["render",o]]);export{u as __pageData,q as default};
